-- v3b01_plan_reading / ex8 — measure a DELETE without deleting
BEGIN;

EXPLAIN (ANALYZE, BUFFERS, WAL)
DELETE FROM perf.orders
WHERE tenant_id = 7 AND status = 'cancelled';

ROLLBACK;

SELECT count(*)::bigint AS rows_to_delete,
       true             AS measured_safely,
       'WAL reports records, full-page images and bytes written; FPI counts'
       || ' spike right after a checkpoint, so the same DELETE costs very'
       || ' different amounts of WAL depending on when it runs.' AS why_wal
FROM perf.orders
WHERE tenant_id = 7 AND status = 'cancelled';

