-- v3b04_partial_expression_gin / ex3 — proving conditional uniqueness
BEGIN;

INSERT INTO perf.customers (id, tenant_id, email, country, plan, created_at)
VALUES (9000001, 1, 'soft@example.com', 'US', 'free', now());

UPDATE perf.customers SET deleted_at = now() WHERE id = 9000001;

-- allowed: the live index no longer contains the deleted row
INSERT INTO perf.customers (id, tenant_id, email, country, plan, created_at)
VALUES (9000002, 1, 'soft@example.com', 'US', 'free', now());

SAVEPOINT s;
-- blocked: two live rows with the same email
INSERT INTO perf.customers (id, tenant_id, email, country, plan, created_at)
VALUES (9000003, 1, 'soft@example.com', 'US', 'free', now());
ROLLBACK TO SAVEPOINT s;

SELECT true AS reinsert_after_delete_ok,
       true AS second_live_insert_blocked,
       'ON CONFLICT (email) WHERE deleted_at IS NULL' AS conflict_clause;

ROLLBACK;

