-- v3b04_partial_expression_gin / ex8 — one order per bay at any instant
CREATE EXTENSION IF NOT EXISTS btree_gist;

CREATE TABLE IF NOT EXISTS perf.dock_slots (
  id       bigserial PRIMARY KEY,
  bay_id   int       NOT NULL,
  order_id bigint    NOT NULL,
  during   tstzrange NOT NULL
);

ALTER TABLE perf.dock_slots
  DROP CONSTRAINT IF EXISTS dock_no_overlap;

ALTER TABLE perf.dock_slots
  ADD CONSTRAINT dock_no_overlap
  EXCLUDE USING gist (bay_id WITH =, during WITH &&);

-- v3b04_partial_expression_gin / challenge — both designs, side by side
CREATE EXTENSION IF NOT EXISTS btree_gin;
SET maintenance_work_mem = '512MB';

-- Design A: ordered B-tree (plus the jsonb_path_ops GIN from ex6)
CREATE INDEX IF NOT EXISTS events_tenant_time_idx
  ON perf.events (tenant_id, occurred_at DESC);

