  ON perf.orders ((coalesce(delivered_at, timestamptz '-infinity')) DESC,
                  id DESC);

ANALYZE perf.orders;

-- v3b07_pagination_and_counting / ex6 — index only the rows being counted
CREATE INDEX IF NOT EXISTS orders_pending_count_idx
  ON perf.orders (id)
  WHERE status = 'pending';

VACUUM (ANALYZE) perf.orders;

-- v3b07_pagination_and_counting / ex7 — sharded counter and its maintenance
CREATE TABLE IF NOT EXISTS perf.event_counts (
  tenant_id int    NOT NULL,
  shard     int    NOT NULL,
  n         bigint NOT NULL DEFAULT 0,
  PRIMARY KEY (tenant_id, shard)
);

CREATE OR REPLACE FUNCTION perf.bump_event_count() RETURNS trigger
LANGUAGE plpgsql AS $$
BEGIN
  INSERT INTO perf.event_counts (tenant_id, shard, n)
  VALUES (NEW.tenant_id, (hashint4(pg_backend_pid()) & 15), 1)
  ON CONFLICT (tenant_id, shard)
  DO UPDATE SET n = perf.event_counts.n + 1;
  RETURN NEW;
END $$;

DROP TRIGGER IF EXISTS events_count_trg ON perf.events;
CREATE TRIGGER events_count_trg
  AFTER INSERT ON perf.events
  FOR EACH ROW EXECUTE FUNCTION perf.bump_event_count();

-- Note: for bulk loads prefer a statement-level trigger with a transition
-- table, or update the counter once per batch in the same transaction.
ANALYZE perf.event_counts;

-- v3b07_pagination_and_counting / challenge — one index per tenant timeline
CREATE INDEX IF NOT EXISTS orders_tenant_placed_id_desc_idx
  ON perf.orders (tenant_id, placed_at DESC, id DESC)
  INCLUDE (total_cents);

VACUUM (ANALYZE) perf.orders;

exercises.prompt:
## Exercise 2 — what VACUUM gives back, and to whom

Edit `ex2/solution.sql` to run this experiment and report it:

1. record `pg_relation_size('perf.orders')` as `size_before`;
2. `DELETE FROM perf.orders WHERE id % 10 = 3;` (10% of rows) — inside a
   transaction you will **commit**, since vacuum cannot reclaim uncommitted
   deletes;
3. record the size again as `size_after_delete`;
4. `VACUUM perf.orders;` and record `size_after_vacuum`;
5. read `free_space` from `pgstattuple` as `reusable_mb`;
6. return **one row, six columns**: the three sizes in MB (one decimal),
   `reusable_mb`, `file_shrank` (boolean), and `explanation` — one sentence.

Then, as a comment, state what you would run if you genuinely needed the
disk space back, and what it would cost.

**Measurable goal:** `file_shrank` is `false` and `reusable_mb` is above 15.

Run: `uv run dojo test v3b08_bloat_vacuum_maintenance ex2`

