-- v3b08_bloat_vacuum_maintenance / ex2 — vacuum reclaims, it does not shrink
-- To actually return the space: VACUUM FULL (ACCESS EXCLUSIVE for the whole
-- rewrite) or pg_repack (brief locks, needs room for a second copy).
CREATE TEMP TABLE sizes (label text, bytes bigint);

INSERT INTO sizes VALUES ('before', pg_relation_size('perf.orders'));

DELETE FROM perf.orders WHERE id % 10 = 3;

INSERT INTO sizes VALUES ('after_delete', pg_relation_size('perf.orders'));

VACUUM perf.orders;

INSERT INTO sizes VALUES ('after_vacuum', pg_relation_size('perf.orders'));

WITH s AS (
  SELECT max(bytes) FILTER (WHERE label = 'before')       AS b,
         max(bytes) FILTER (WHERE label = 'after_delete') AS d,
         max(bytes) FILTER (WHERE label = 'after_vacuum') AS v
  FROM sizes
),
p AS (
  SELECT free_space::numeric AS free_bytes FROM pgstattuple('perf.orders')
)
SELECT round(s.b::numeric / 1024 / 1024, 1)          AS size_before_mb,
       round(s.d::numeric / 1024 / 1024, 1)          AS size_after_delete_mb,
       round(s.v::numeric / 1024 / 1024, 1)          AS size_after_vacuum_mb,
       round(p.free_bytes / 1024 / 1024, 1)          AS reusable_mb,
       (s.v < s.b)                                   AS file_shrank,
       'VACUUM records freed space in the free space map for this table''s '
       || 'future inserts and only truncates empty pages at the physical end '
       || 'of the file, which interleaved deletions do not produce.'
                                                     AS explanation
FROM s CROSS JOIN p;

