-- v3b08_bloat_vacuum_maintenance / ex3 — room on the page, and one less index
ALTER TABLE perf.orders SET (fillfactor = 85);

-- Full index on a column that changes five times per order: every transition
-- was a non-HOT update. The queue only ever reads one status.
DROP INDEX IF EXISTS perf.orders_status_placed_idx;

CREATE INDEX IF NOT EXISTS orders_pending_idx
  ON perf.orders (placed_at)
  WHERE status = 'pending';

-- fillfactor applies to newly written pages only; rewrite to apply it now.
VACUUM FULL perf.orders;
ANALYZE perf.orders;
